namespace {
//! The host image of either image kind (a DeviceImage is synced and marked modified).
template <typename T> VoxelImageT<T>& host_of(VoxelImageT<T>& v) { return v; }
template <typename T> VoxelImageT<T>& host_of(DeviceImage<T>& v) { return v.host_mut(); }
template <typename T> const VoxelImageT<T>& cmeta_of(const VoxelImageT<T>& v) { return v; }  // header data only: no sync
template <typename T> const VoxelImageT<T>& cmeta_of(const DeviceImage<T>& v) { return v.unsynced(); }
}  // namespace

// voxlib grow(vImg, midv, minv, maxv): interior voxels in [minv, maxv] next to a midv voxel become midv.
template <Image I> void grow(I& v, voxel_t<I> midv, voxel_t<I> minv, voxel_t<I> maxv) {
    detail::run_stencil<op::growRange, kernels::growRange<voxel_t<I>>>(
        v, 1, [&](auto& m) { ::grow(m, midv, minv, maxv); }, midv, minv, maxv);
}
// VoxLib::growOutSideValue: replaces the runs of vo from every face by vnew (six line scans), then grows each by nHoleSize.
template <Image I> bool growOutSideValue(I& v, int vo, int vnew, int nHoleSize) {
    using T = voxel_t<I>;
    auto inRange = [](int l) { return double(l) >= double(std::numeric_limits<T>::lowest()) && double(l) <= double(std::numeric_limits<T>::max()); };
    if (get_backend() == Backend::Voxlib || !inRange(vo) || !inRange(vnew))  // voxlib converts out-of-range labels its own way
        return VoxLib::growOutSideValue(host_of(v), vo, vnew, nHoleSize);
    detail::run_stencil<op::growOutside, kernels::growOutside<T>>(
        v, detail::Passes(1, std::max(1, cmeta_of(v).size3().z)), [&](auto& m) { VoxLib::growOutSideValue(m, vo, vnew, 0); }, T(vo), T(vnew));
    for (int i = 0; i < nHoleSize; ++i) vxhl::grow(v, T(vo), T(vnew), T(vnew));
    for (int i = 0; i < nHoleSize; ++i) vxhl::grow(v, T(vnew), T(vo), T(vo));
    return true;
}

// ---- F6: outputs of another size (run_remap)
namespace {
//! voxlib cropD / growBox as one remapBox kernel: output voxel o reads input o + off; fill: outside
//! [bgn, end) is fillValue, else clamped to the image. The result replaces v.
template <Image I, typename Ref>
void remap_box(I& v, int3 no, dbl3 X0, int3 off, int3 bgn, int3 end, bool fill, double fillValue, Ref&& ref) {
    using T = voxel_t<I>;
    const int3 n = v.size3();
    auto zIn = [&](int k0, int k1) {
        const int a = std::clamp(k0 + off.z, 0, n.z - 1), b = std::clamp(k1 - 1 + off.z, 0, n.z - 1);
        return std::pair<int, int>(a, b + 1);
    };
    const dbl3 dx = cmeta_of(v).dx();
    v = detail::run_remap<op::remapBox, kernels::remapBox<T>, T>(
        std::as_const(v), no, dx, X0, ref, zIn, int32_t(off.x), int32_t(off.y), int32_t(off.z), int32_t(bgn.x),
        int32_t(bgn.y), int32_t(bgn.z), int32_t(end.x), int32_t(end.y), int32_t(end.z), int32_t(fill), fillValue);
}
}  // namespace

template <Image I> void cropD(I& v, int3 frm, int3 to, int emptylyrs, voxel_t<I> eLyrsValue, bool verbose) {
    using T = voxel_t<I>;
    const int3 n = v.size3();
    if (to.x <= 0) to.x += n.x;
    if (to.y <= 0) to.y += n.y;
    if (to.z <= 0) to.z += n.z;
    const bool ok = frm.x >= 0 && frm.y >= 0 && frm.z >= 0 && to.x <= n.x && to.y <= n.y && to.z <= n.z &&
                    to.x > frm.x && to.y > frm.y && to.z > frm.z && emptylyrs >= 0;
    if (get_backend() == Backend::Voxlib || verbose || !ok) return host_of(v).cropD(frm, to, emptylyrs, eLyrsValue, verbose);
    const int3 e(emptylyrs, emptylyrs, emptylyrs);
    remap_box(v, to - frm + e + e, cmeta_of(v).X0() + (frm - e) * cmeta_of(v).dx(), frm - e, frm, to, emptylyrs != 0,
              double(eLyrsValue), [&](const VoxelImageT<T>& h) { VoxelImageT<T> r = h; r.cropD(frm, to, emptylyrs, eLyrsValue); return r; });
}
template <Image I> void growBox(I& v, int nLayers) {
    using T = voxel_t<I>;
    if (get_backend() == Backend::Voxlib || nLayers < 0) return host_of(v).growBox(nLayers);
    if (nLayers == 0) return;
    const int3 l(nLayers, nLayers, nLayers);
    remap_box(v, v.size3() + l + l, cmeta_of(v).X0() - l * cmeta_of(v).dx(), int3(0, 0, 0) - l, int3(0, 0, 0), v.size3(), false, 0.0,
              [&](const VoxelImageT<T>& h) { VoxelImageT<T> r = h; r.growBox(nLayers); return r; });
}
template <Image I> std::array<double, 5> otsu_minAvgThresholdAvgMax(const I& v, intOr<voxel_t<I>> minvi, intOr<voxel_t<I>> maxvi,
                                                                   double skipFrac, int maxBins) {
    using T = voxel_t<I>;
    const HistBins bins = otsuBins(minvi, maxvi, std::is_integral_v<T>, maxBins);
    if (skipFrac != 0) {  // the margins: voxlib, on the host
        if constexpr (std::is_same_v<I, VoxelImageT<T>>) return ::otsu_minAvgThresholdAvgMax(v, bins, minvi, maxvi, skipFrac);
        else return ::otsu_minAvgThresholdAvgMax(v.host(), bins, minvi, maxvi, skipFrac);
    }
    const dbls h = convertToDbls(vxhl::histogram(v, bins.shift, bins.span, bins.nBins, double(minvi), double(maxvi)));
    return otsu_minAvThresholdAvMx(h, 0, bins.nBins - 1, bins.shift, bins.scale());
}
template <Image I> MaskOf<I> threshold01_otsu(const I& v, int minvi, int maxvi, double skipFrac) {
    using T = voxel_t<I>;
    const double t = vxhl::otsu_minAvgThresholdAvgMax(v, minvi, maxvi, skipFrac)[2];  // v < t: class 0
    const VoxelImageT<T>& hdr = cmeta_of(v);
    return detail::run_remap<op::threshold01, kernels::threshold01<T>, uint8_t>(
        v, v.size3(), hdr.dx(), hdr.X0(),
        [&](const VoxelImageT<T>& h) {  // voxlib's apply step with this threshold
            VoxelImageT<uint8_t> msk(h.size3(), 1, h.dx(), h.X0());
            for (std::size_t i = 0; i < h.data_.size(); ++i) if (h.data_[i] < t) msk.data_[i] = 0;
            return msk;
        },
        [](int k0, int k1) { return std::pair<int, int>(k0, k1); }, t);
}
// voxlib VoxelImageT::rotate (Python redirect / direction): swap x with y or z, or flip x ('-').
template <Image I> void redirect(I& v, char direction) {
    using T = voxel_t<I>;
    const char d = char(std::tolower(direction));
    if (get_backend() == Backend::Voxlib || (d != 'z' && d != 'y' && d != '-')) return host_of(v).rotate(direction);
    const VoxelImageT<T>& hdr = cmeta_of(v);
    const int3 n = v.size3();
    dbl3 X0 = hdr.X0(), dx = hdr.dx();
    auto ref = [&](const VoxelImageT<T>& h) { VoxelImageT<T> r = h; r.rotate(direction); return r; };
    if (d == '-') {
        std::cout << " x<->" << direction << "  -> flipping image,  x origin will be invalid " << std::endl;
        v = detail::run_remap<op::flipX, kernels::flipX<T>, T>(std::as_const(v), n, dx, X0, ref,
                                                               [](int k0, int k1) { return std::pair<int, int>(k0, k1); });
        return;
    }
    (std::cout << " x<->" << direction << " ").flush();
    if (d == 'z') {
        std::swap(X0.x, X0.z), std::swap(dx.x, dx.z);
        v = detail::run_remap<op::swapXZ, kernels::swapXZ<T>, T>(std::as_const(v), int3(n.z, n.y, n.x), dx, X0, ref,
                                                                 [&](int, int) { return std::pair<int, int>(0, n.z); });
    } else {
        std::swap(X0.x, X0.y), std::swap(dx.x, dx.y);
        v = detail::run_remap<op::swapXY, kernels::swapXY<T>, T>(std::as_const(v), int3(n.y, n.x, n.z), dx, X0, ref,
                                                                 [](int k0, int k1) { return std::pair<int, int>(k0, k1); });
    }
}
namespace {
//! A copy of v (VoxelImageT or DeviceImage; a DeviceImage on the GPU is copied there, by remapBox with no offset).
template <typename T> VoxelImageT<T> copy_of(const VoxelImageT<T>& v) { return v; }
template <typename T> DeviceImage<T> copy_of(const DeviceImage<T>& v) {
    const VoxelImageT<T>& hdr = v.unsynced();
    const int3 n = v.size3(), o(0, 0, 0);
    return detail::run_remap<op::remapBox, kernels::remapBox<T>, T>(
        v, n, hdr.dx(), hdr.X0(), [](const VoxelImageT<T>& h) { return h; }, [](int k0, int k1) { return std::pair<int, int>(k0, k1); },
        int32_t(0), int32_t(0), int32_t(0), int32_t(0), int32_t(0), int32_t(0), int32_t(n.x), int32_t(n.y), int32_t(n.z), int32_t(0), 0.0);
}

//! voxlib resampleMean / resampleMax / resampleMode: factor < 1 upsamples (nearest, the same in all three),
//! factor > 1 reduces n³ blocks with the kernel KDn, ~1 copies.
template <typename OpDn, template <class> class KDn, Image I, typename Ref>
std::remove_const_t<I> resample_blocks(const I& v, double factor, Ref&& ref) {
    using T = voxel_t<I>;
    const VoxelImageT<T>& hdr = cmeta_of(v);
    const int3 n = v.size3();
    if (factor < .999) {
        const int k = int(1. / factor + 0.5);
        return detail::run_remap<op::resampleUp, kernels::resampleUp<T>, T>(
            v, k * n, hdr.dx() / k, hdr.X0() / k, ref,
            [&, k](int k0, int k1) { return std::pair<int, int>((2 * k0 + 1) / (2 * k), (2 * (k1 - 1) + 1) / (2 * k) + 1); },
            int32_t(k));
    }
    if (factor > 1.001) {
        const int k = int(factor + 0.5);
        return detail::run_remap<OpDn, KDn<T>, T>(
            v, n / k, hdr.dx() * k, hdr.X0() * k, ref, [k](int k0, int k1) { return std::pair<int, int>(k0 * k, k1 * k); },
            int32_t(k));
    }
    return copy_of(v);
}
}  // namespace

template <Image I> std::remove_const_t<I> copy(const I& v) { return copy_of(v); }
// voxlib resampleMean (Python resample / resample_mean): > 1 averages the n³ blocks.
template <Image I> std::remove_const_t<I> resampleMean(const I& v, double factor) {
    return resample_blocks<op::resampleMeanDn, kernels::resampleMeanDn>(
        v, factor, [&](const VoxelImageT<voxel_t<I>>& h) { return ::resampleMean(h, factor); });
}
// voxlib resampleMax (Python resample_max): > 1 takes the maximum of the n³ blocks.
template <Image I> std::remove_const_t<I> resampleMax(const I& v, double factor) {
    return resample_blocks<op::resampleMaxDn, kernels::resampleMaxDn>(
        v, factor, [&](const VoxelImageT<voxel_t<I>>& h) { return ::resampleMax(h, factor); });
}
// voxlib resampleMode (Python resample_mode): > 1 takes the most frequent value of the n³ blocks.
template <Image I> std::remove_const_t<I> resampleMode(const I& v, double factor) {
    return resample_blocks<op::resampleModeDn, kernels::resampleModeDn>(
        v, factor, [&](const VoxelImageT<voxel_t<I>>& h) { return ::resampleMode(h, factor); });
}
// voxlib resliceZ (Python reslice_z): resample z only; factor ~0 takes dx.x/dx.z.
template <Image I> std::remove_const_t<I> resliceZ(const I& v, double factor) {
    using T = voxel_t<I>;
    const VoxelImageT<T>& hdr = cmeta_of(v);
    if (factor < 1e-64) { factor = hdr.dx().x / hdr.dx().z; (std::cout << " nResample: " << factor << ", ").flush(); }
    auto ref = [&](const VoxelImageT<T>& h) { return ::resliceZ(h, factor); };
    const int3 n = v.size3();
    if (factor < .999) {
        dbl3 dx = hdr.dx(), X0 = hdr.X0();
        dx.z *= factor, X0.z *= factor;
        return detail::run_remap<op::resliceUp, kernels::resliceUp<T>, T>(
            v, int3(n.x, n.y, int(n.z / factor)), dx, X0, ref,
            [&](int k0, int k1) { return std::pair<int, int>(int((0.5 + k0) * factor), int((0.5 + k1 - 1) * factor) + 1); }, factor);
    }
    if (factor > 1.001) {
        if constexpr (std::is_floating_point_v<T>) {  // voxlib sums and divides in float: no kernel (Vulkan ignores strict_float)
            if constexpr (std::is_same_v<I, VoxelImageT<T>>) return ::resliceZ(v, factor);
            else return DeviceImage<T>(::resliceZ(v.host(), factor));
        }
        std::cout << "resliceZ >1 not tested" << std::endl;
        const int k = int(factor + 0.5);
        return detail::run_remap<op::resliceDn, kernels::resliceDn<T>, T>(
            v, int3(n.x, n.y, n.z / k), hdr.dx() * k, hdr.X0() * k,
            ref,
            [k](int k0, int k1) { return std::pair<int, int>(k0 * k, k1 * k); }, int32_t(k));
    }
    return copy_of(v);
}
template <Image I> void shrinkBox(I& v, int nLayers) {
    const int3 b(nLayers, nLayers, nLayers);
    vxhl::cropD(v, b, v.size3() - b, 0, voxel_t<I>(1), false);
}


// a (op) b for a second image: code 0 && / 1 || / 2 != / 3 && ! / 4 + / 5 -
template <Image I, Image J, typename Ref>
void pair_op(I& a, const J& b, int code, Ref&& ref) {
    using T = voxel_t<I>;
    static_assert(std::is_same_v<T, voxel_t<J>>);
    if (a.size3() != b.size3()) throw std::runtime_error("Image sizes do not match");
    const detail::Aux<T> o(b);
    detail::run_stencil<op::pairOp, kernels::pairOp<T>>(a, 1, [&](auto& m) { ref(m, o.host()); }, o, int32_t(code));
}
template <Image I, Image J> void and_(I& a, const J& b) { pair_op(a, b, 0, [](auto& m, const auto& o) { ::and_(m, o); }); }
template <Image I, Image J> void or_(I& a, const J& b)  { pair_op(a, b, 1, [](auto& m, const auto& o) { ::or_(m, o); }); }
template <Image I, Image J> void xor_(I& a, const J& b) { pair_op(a, b, 2, [](auto& m, const auto& o) { ::xor_(m, o); }); }
template <Image I, Image J> void not_(I& a, const J& b) { pair_op(a, b, 3, [](auto& m, const auto& o) { ::not_(m, o); }); }
template <Image I, Image J> void addEq(I& a, const J& b) { pair_op(a, b, 4, [](auto& m, const auto& o) { ::addEq(m, o); }); }
template <Image I, Image J> void subEq(I& a, const J& b) { pair_op(a, b, 5, [](auto& m, const auto& o) { ::subEq(m, o); }); }

// operate: the operation character is a kernel argument; an unsupported one (and an empty string) runs voxlib, which throws.
template <Image I> void operateUnary(I& m, const std::string& opr) {
    using T = voxel_t<I>;
    if (opr.empty() || std::string("~!-").find(opr[0]) == std::string::npos) return ::operateUnary(host_of(m), opr);
    detail::run_stencil<op::operateUnary, kernels::operateUnary<T>>(
        m, 1, [&](auto& h) { ::operateUnary(h, opr); }, int32_t(opr[0]));
}
template <Image I, Image J> void operateImg(I& m, const std::string& opr, const J& img2, double shift) {
    using T = voxel_t<I>;
    static_assert(std::is_same_v<T, voxel_t<J>>);
    if (opr.empty() || std::string("+-*/&|%").find(opr[0]) == std::string::npos) return ::operateImg(host_of(m), opr, cmeta_of(img2), shift);
    if (m.size3() != img2.size3()) throw std::runtime_error("Image dimensions do not match for operate");
    const detail::Aux<T> o(img2);
    detail::run_stencil<op::operateImg, kernels::operateImg<T>>(
        m, 1, [&](auto& h) { ::operateImg(h, opr, o.host(), shift); }, o, int32_t(opr[0]), shift);
}
template <Image I> void operateScalar(I& m, const std::string& opr, double val) {
    using T = voxel_t<I>;
    if (opr.empty() || std::string("=+-*/&|%be").find(opr[0]) == std::string::npos) return ::operateScalar(host_of(m), opr, val);
    detail::run_stencil<op::operateScalar, kernels::operateScalar<T>>(
        m, 1, [&](auto& h) { ::operateScalar(h, opr, val); }, int32_t(opr[0]), val);
}
template <Image I> void threshold101(I& v, voxel_t<I> bgn, voxel_t<I> end) {
    detail::run_stencil<op::threshold101, kernels::threshold101<voxel_t<I>>>(v, 1, [&](auto& m) { ::threshold101(m, bgn, end); }, bgn, end);
}
template <Image I> void circleOut(I& v, int X0, int Y0, int R, char dir, voxel_t<I> outVal) {
    if (dir != 'z' && dir != 'x') return ::circleOut(host_of(v), X0, Y0, R, dir, outVal);  // voxlib's error
    detail::run_stencil<op::circleOut, kernels::circleOut<voxel_t<I>>>(
        v, 1, [&](auto& m) { ::circleOut(m, X0, Y0, R, dir, outVal); }, int32_t(X0), int32_t(Y0), int32_t(R),
        int32_t(dir == 'z' ? 0 : 1), outVal);
}
template <Image I, Image J> void mapToFrom(I& v, const J& v2, voxel_t<I> vmin, voxel_t<I> vmax, double scale, double shift) {
    using T = voxel_t<I>;
    static_assert(std::is_same_v<T, voxel_t<J>>);
    const VoxelImageT<T>& a = cmeta_of(v);
    const VoxelImageT<T>& b = cmeta_of(v2);
    int3 Dn((a.X0() - b.X0()) / a.dx() + 0.5);  // as voxlib
    const detail::Aux<T> src(v2);
    auto vref = [&](auto& m) { ::mapToFrom(m, src.host(), vmin, vmax, scale, shift); };
    if (a.size3() != b.size3() || Dn.x != 0 || Dn.y != 0 || Dn.z != 0) return vref(host_of(v));  // other grid: voxlib
    detail::run_stencil<op::mapFrom, kernels::mapFrom<T>>(v, 1, vref, src, vmin, vmax, scale, shift);
}

// paint / paint_add: the shape's parameters are kernel arguments; voxel centres are (index + 0.5)·dx + X0.
template <Image I> void paint_shape(I& v, const VoxLib::shape& sh, int mode) {
    using T = voxel_t<I>;
    auto ref = [&](auto& m) { if (mode == 0) ::VoxLib::paint(m, sh); else ::VoxLib::paintAdd(m, sh); };
    const VoxelImageT<T>& meta = cmeta_of(v);
    const dbl3 dx = meta.dx(), x0 = meta.X0();
    const int32_t iv = sh.insidev;
    if (sh.polyType == 's' || sh.polyType == 'c' || sh.polyType == 'k') {
        std::array<double, 7> p{};
        if (sh.polyType == 's') p = static_cast<const VoxLib::sphere&>(sh).params();
        if (sh.polyType == 'c') p = static_cast<const VoxLib::cylinder&>(sh).params();
        if (sh.polyType == 'k') p = static_cast<const VoxLib::kube&>(sh).params();
        const int32_t kind = sh.polyType == 's' ? 0 : sh.polyType == 'c' ? 1 : 2;
        detail::run_stencil<op::paintShape, kernels::paintShape<T>>(
            v, 1, ref, kind, int32_t(mode), iv, dx.x, dx.y, dx.z, x0.x, x0.y, x0.z, p[0], p[1], p[2], p[3], p[4], p[5], p[6]);
    } else if (sh.polyType == 't') {
        const auto p = static_cast<const VoxLib::triangular&>(sh).params();
        detail::run_stencil<op::paintTriangular, kernels::paintTriangular<T>>(
            v, 1, ref, int32_t(mode), iv, dx.x, dx.y, dx.z, x0.x, x0.y, x0.z, p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7], p[8], p[9]);
    } else {
        ref(host_of(v));  // other shapes (not exposed to Python): voxlib
    }
}
template <Image I> void paint(I& v, const VoxLib::shape& sh) { paint_shape(v, sh, 0); }
template <Image I> void paintAdd(I& v, const VoxLib::shape& sh) { paint_shape(v, sh, 1); }

template <Image I, Image J> void copyFrom(I& a, const J& b) {
    pair_op(a, b, 6, [](auto& m, const auto& o) { m.data_ = o.data_; });
}
// delense032's merge: where `other` equals `value`, the image is set to it
template <Image I, Image J> void set_where_equal(I& a, const J& other, voxel_t<I> value) {
    using T = voxel_t<I>;
    if (a.size3() != other.size3()) throw std::runtime_error("Image sizes do not match");
    const detail::Aux<T> o(other);
    detail::run_stencil<op::setWhereEqual, kernels::setWhereEqual<T>>(
        a, 1, [&](auto& m) { const auto& h = o.host(); for (std::size_t i = 0; i < m.data_.size(); ++i) if (h.data_[i] == value) m.data_[i] = value; }, o, value);
}
namespace {
//! Run f(DeviceImage&) on `v`: a VoxelImageT is copied in and moved back after f succeeded (so an exception leaves it intact).
template <typename T, typename F> void on_device(VoxelImageT<T>& v, F&& f) { DeviceImage<T> d(v); f(d); v = std::move(d.host_mut()); }
template <typename T, typename F> void on_device(DeviceImage<T>& d, F&& f) { f(d); }
}  // namespace

// ---- voxlib keepLargest / keepLargestvv (voxelRegions.h): connected components on the device,
// gather-only (generators/ccl_gen.cpp). Steps: labels from the voxels of `lab` in [labLo, labHi]
// (rounds of line scans until nothing changes), per-component counts of the voxels of `cnt` in [cntLo, cntHi]
// (subtree sums along the parent pointers), the largest (ties: the first in raster order, as voxlib's
// label order), applied to v. voxlib runs for the voxlib backend, 2^28 voxels or more (packed int32
// labels) and when a step has no kernel.
namespace {
struct CclFallback : std::runtime_error {
    CclFallback() : std::runtime_error("vxhl: ccl step without kernel") {}
};
template <Image I, typename U> using SameKind = std::conditional_t<std::is_same_v<std::remove_const_t<I>, DeviceImage<voxel_t<I>>>,
                                                                  DeviceImage<U>, VoxelImageT<U>>;
template <typename T> const VoxelImageT<T>& host_view(const VoxelImageT<T>& v) { return v; }
template <typename T> const VoxelImageT<T>& host_view(const DeviceImage<T>& v) { return v.host(); }

//! The packed labels P of the voxels of `lab` in [lo, hi] (see ccl_gen.cpp).
template <Image J> SameKind<J, int32_t> ccl_labels(const J& lab, voxel_t<J> lo, voxel_t<J> hi) {
    using T = voxel_t<J>;
    const VoxelImageT<T>& h = cmeta_of(lab);
    const int3 n = lab.size3();
    auto fail = [](const VoxelImageT<T>&) -> VoxelImageT<int32_t> { throw CclFallback(); };
    auto same = [](int k0, int k1) { return std::pair<int, int>(k0, k1); };
    SameKind<J, int32_t> P = detail::run_remap<op::cclInit, kernels::cclInit<T>, int32_t>(lab, n, h.dx(), h.X0(), fail, same, lo, hi);
    auto nofb = [](auto&) -> long long { throw CclFallback(); };
    int rounds = 0;
    for (long long changed = 1; changed; ++rounds) {
        changed = detail::run_stencil_count<op::cclLabel, kernels::cclLabel<int32_t>>(P, detail::Passes(1, n.z), nofb);
    }
    if (vxlDebug()) std::cerr << "vxhl ccl: " << rounds << " label rounds" << std::endl;
    return P;
}

//! The label (smallest raster index) of the component with the most voxels of `cnt` in [lo, hi], or
//! -1 when every count is 0 (voxlib then keeps no component).
template <Image I, typename LP> int ccl_largest(const I& cnt, const LP& P, voxel_t<I> lo, voxel_t<I> hi) {
    using T = voxel_t<I>;
    const VoxelImageT<T>& h = cmeta_of(cnt);
    const int3 n = cnt.size3();
    auto fail = [](const VoxelImageT<T>&) -> VoxelImageT<int32_t> { throw CclFallback(); };
    auto same = [](int k0, int k1) { return std::pair<int, int>(k0, k1); };
    using LS = SameKind<I, int32_t>;
    const LS W = detail::run_remap<op::cclWeight, kernels::cclWeight<T>, int32_t>(cnt, n, h.dx(), h.X0(), fail, same, lo, hi);
    LS S = copy_of(W);
    const detail::Aux<int32_t> ap(P), aw(W);
    auto nofb = [](auto&) -> long long { throw CclFallback(); };
    int rounds = 0;
    for (long long changed = 1; changed; ++rounds) {
        if (rounds > 100000) throw std::logic_error("vxhl ccl: sums do not converge");
        changed = detail::run_stencil_count<op::cclSum, kernels::cclSum<int32_t>>(S, detail::Passes(1, n.z), nofb, ap, aw);
    }
    if (vxlDebug()) std::cerr << "vxhl ccl: " << rounds << " sum rounds" << std::endl;
    detail::run_stencil<op::cclRoots, kernels::cclRoots<int32_t>>(S, 1, [](auto&) { throw CclFallback(); }, ap);
    return detail::run_reduce<op::cclBest, kernels::cclBest<int32_t>, 2>(
        S, [](const VoxelImageT<int32_t>&) -> int { throw CclFallback(); }, [&](auto pass) {
            const detail::PerZ<2> o = pass();
            double m = -1, idx = -1;
            for (int z = 0; z < n.z; ++z)
                if (o[0][z] > m) m = o[0][z], idx = o[1][z];  // layers in raster order: the first wins ties
            return m > 0 ? int(idx) : -1;
        });
}

//! Outside component `best` of P: mode 0 every voxel of v, mode 1 those in [lo, hi] become `value`.
template <Image I, typename LP> void ccl_apply(I& v, const LP& P, int best, int mode, voxel_t<I> lo, voxel_t<I> hi, voxel_t<I> value) {
    const detail::Aux<int32_t> ap(P);
    detail::run_stencil<op::cclApply, kernels::cclApply<voxel_t<I>>>(
        v, 1,
        [&](auto& m) {
            const auto& p = ap.host();
            for (std::size_t i = 0; i < m.data_.size(); ++i) {
                const int32_t q = p.data_[i];
                if (!(q >= 0 && (q >> 3) == best) && (mode == 0 || (lo <= m.data_[i] && m.data_[i] <= hi))) m.data_[i] = value;
            }
        },
        ap, int32_t(best), int32_t(mode), lo, hi, value);
}
template <typename T> bool ccl_supported(int3 n) {
    const long long nv = (long long)n.x * n.y * n.z;
    return get_backend() != Backend::Voxlib && nv > 0 && nv < (1LL << 28);
}
}  // namespace

template <Image I, Image J>
void keepLargest(I& v, const J& grad, voxel_t<I> minvv, voxel_t<I> maxvv, voxel_t<I> minvg, voxel_t<I> maxvg) {
    using T = voxel_t<I>;
    auto voxlib = [&] { ::keepLargest(host_of(v), host_view(grad), minvv, maxvv, minvg, maxvg); };
    if (v.size3() != grad.size3()) throw std::runtime_error("Image sizes do not match");
    if (!ccl_supported<T>(v.size3())) return voxlib();
    try {
        const auto P = ccl_labels(grad, minvg, maxvg);
        ccl_apply(v, P, ccl_largest(std::as_const(v), P, minvv, maxvv), 0, T(0), T(0), maxT(T));
    } catch (const CclFallback&) {
        voxlib();
    }
}
template <Image I> void keepLargestvv(I& v, voxel_t<I> minvv, voxel_t<I> maxvv) {
    using T = voxel_t<I>;
    if (!ccl_supported<T>(v.size3())) return ::keepLargestvv(host_of(v), minvv, maxvv);
    try {
        const auto P = ccl_labels(std::as_const(v), minvv, maxvv);
        ccl_apply(v, P, ccl_largest(std::as_const(v), P, minvv, maxvv), 1, minvv, maxvv, T(maxT(T) - 1));
    } catch (const CclFallback&) {
        ::keepLargestvv(host_of(v), minvv, maxvv);
    }
}

// ---- VoxLib::meanWide (Python mean_wide): the prep and the iterations run on DeviceImages.
// Host steps, as in voxlib: with VXL_DEBUG set, the dump*.raw files (each downloads the image).
// The building blocks are public (voxlide.h, not bound in Python) so each is tested on its own: the end-to-end
// result is smooth enough to hide errors in the border planes or in a neighbour-count threshold.
template <Image I> void padEdges(I& v) {  // meanWide's border planes (see generators/pad_edges_gen.cpp)
    using T = voxel_t<I>;
    auto ref = [&](auto& m) {
        const int3 n = m.size3();
        for (int i : {1, 2, 3}) {
            m.replaceyLayer(n[1] - 1 - i, 4), m.replaceyLayer(i, n[1] - 5);
            m.replacexLayer(n[0] - 1 - i, 4), m.replacexLayer(i, n[0] - 5);
            m.setLayer(n[2] - 1 - i, &m(0, 0, 4)), m.setLayer(i, &m(0, 0, n[2] - 5));
        }
    };
    detail::run_stencil<op::padEdges, kernels::padEdges<T>>(v, detail::Passes(1, std::max(1, v.size3().z)), ref);
}
template <Image I> void meanFilter(I& v) {  // ::mean; floats: voxlib (its int sum truncates at every step)
    using T = voxel_t<I>;
    auto ref = [&](auto& m) { m = ::mean(m); };
    if constexpr (std::is_floating_point_v<T>) ref(host_of(v));
    else detail::run_stencil<op::meanFilter, kernels::meanFilter<T>>(v, 1, ref);
}
template <Image I, Image J> void setWhereAbove(I& v, const J& g, voxel_t<I> thresh, voxel_t<I> value) {
    using T = voxel_t<I>;
    const detail::Aux<T> ga(g);
    auto ref = [&](auto& m) { const auto& h = ga.host(); for (std::size_t i = 0; i < m.data_.size(); ++i) if (h.data_[i] > thresh) m.data_[i] = value; };
    if constexpr (std::is_floating_point_v<T>) ref(host_of(v));
    else detail::run_stencil<op::setWhereAbove, kernels::setWhereAbove<T>>(v, 1, ref, ga, thresh, value);
}
template <Image I, Image J> void meanWideStep(I& v, int nW, voxel_t<I> lowerB, voxel_t<I> upperB, const J& g, voxel_t<I> gradthresh) {
    using T = voxel_t<I>;
    const detail::Aux<T> ga(g);
    auto ref = [&](auto& m) { VoxelImageT<T> gc = ga.host(); m = ::meanWide(m, nW, lowerB, upperB, gc, gradthresh); };
    if constexpr (std::is_floating_point_v<T>) ref(host_of(v));
    else detail::run_stencil<op::meanWideStep, kernels::meanWideStep<T>>(v, detail::Passes(1, nW), ref, ga, int32_t(nW), lowerB, upperB, gradthresh);
}

template <Image I> bool meanWide(I& vImg, int nW, int noisev, int avg, int delta, int nItrs, std::string smoothImg) {
    using T = voxel_t<I>;
    if constexpr (std::is_floating_point_v<T>) {  // voxlib's int sums truncate float voxels at every step: no kernel
        return VoxLib::meanWide(host_of(vImg), nW, noisev, avg, delta, nItrs, smoothImg);
    } else {
        if (get_backend() == Backend::Voxlib || nW < 0) return VoxLib::meanWide(host_of(vImg), nW, noisev, avg, delta, nItrs, smoothImg);
        std::cout << "  meanWide:  nW:" << nW << "  noisev:" << noisev << "  avg:" << avg << "  delta:" << delta << "  nIterations:" << nItrs
                  << "  smoothImg:" << smoothImg << std::endl;
        if (avg == 0) {
            const std::array<double, 5> thresholdsOtsu = vxhl::otsu_minAvgThresholdAvgMax(vImg, 0, 254, 0.2);
            avg = thresholdsOtsu[3];
            std::cout << "  avg:" << avg << "  nW:" << nW << std::endl;
        }
        if (!nW) return true;
        on_device(vImg, [&](DeviceImage<T>& d) {
            vxhl::growBox(d, nW + 5);
            padEdges(d);
            const Tint minvv = std::max(avg - delta, 1);
            const Tint maxvv = std::min(avg + delta, imaxT(T) - 2);
            T minvnrw = std::max(avg - delta / 2, 1);
            T maxvnrw = std::min(avg + delta / 2, imaxT(T) - 2);
            if (smoothImg.empty()) vxhl::bilateralX(d, 6, 3, float(noisev * noisev), 0.05f, 12.f);
            const VoxelImageT<T>& hdr = d.unsynced();
            DeviceImage<T> grad{VoxelImageT<T>(d.size3(), T(0), hdr.dx(), hdr.X0())};
            if (!smoothImg.empty()) {
                grad = DeviceImage<T>(vxhl::magGradient(VoxelImageT<T>(smoothImg, readOpt::procAndConvert), 16));
            } else {
                copyFrom(grad, d);
                vxhl::median(grad), meanFilter(grad), vxhl::median(grad);
                vxhl::magGradient(grad, 16);
            }
            vxhl::median(grad);
            if (vxlDebug()) grad.host().write("dumpGrad5.raw");
            double threshGrad = 2.5 * noisev;
            (std::cout << "  threshGrad:" << threshGrad << ",  ").flush();
            if (vxlDebug()) d.host().write("dumpImg4.raw");
            vxhl::keepLargest(d, grad, T(2), T(maxT(T) - 2), T(0), T(threshGrad));
            if (vxlDebug()) d.host().write("dumpImg5.raw");
            vxhl::replaceRange(d, T(0), minvnrw, T(minvv - 1));
            vxhl::replaceRange(d, maxvnrw, maxT(T), T(maxvv + 1));
            vxhl::median(d), vxhl::median(d);
            setWhereAbove(d, grad, T(std::min(1.50 * threshGrad, dmaxT(T))), T(maxvv + 1));
            vxhl::grow(d, T(maxvv + 1), T(avg), maxT(T));
            vxhl::grow(d, T(minvv - 1), T(0), T(avg));
            for (int i = 0; i < nItrs; ++i) {
                threshGrad += 1 + 0.5 * noisev;
                threshGrad *= 1 + 1.5 * i / (1. + nItrs);
                minvnrw = std::max(minvnrw - delta / 10 - 2, Tint(minvv));
                maxvnrw = std::min(maxvnrw + delta / 10 + 2, Tint(maxvv));
                std::cout << " threshGrad:" << std::min(0.2 * threshGrad, dmaxT(T)) << " minvnrw:" << int(minvnrw) << " maxvnrw:" << int(maxvnrw) << " " << std::endl;
                meanWideStep(d, i % nW + 1, minvnrw, maxvnrw, grad, T(std::min(0.2 * threshGrad, dmaxT(T))));
            }
            if (vxlDebug()) d.host().write("dumpImg6.raw");
            vxhl::shrinkBox(d, nW + 5);
        });
        (std::cout << ".").flush();
        return true;
    }
}


// voxlib VoxelImageT::fillHoles: shrink/grow chains against copies of the image; here all on DeviceImages.
template <Image I> void fillHoles(I& v, int maxHoleRadius) {
    using T = voxel_t<I>;
    if (get_backend() == Backend::Voxlib) return ::fillHoles(host_of(v), maxHoleRadius);
    on_device(v, [&](DeviceImage<T>& self) {
        DeviceImage<T> tmp{VoxelImageT<T>(self.size3(), T(0))};
        copyFrom(tmp, self);
        shrinkPore(tmp);
        for (int i = 0; i < 6; ++i) { growPore(tmp); or_(tmp, self); }
        copyFrom(self, tmp);
        growPore(tmp);
        for (int i = 0; i < 4; ++i) { shrinkPore(tmp); and_(tmp, self); }
        copyFrom(self, tmp);
        if (maxHoleRadius > 1) {
            for (int i = 0; i < maxHoleRadius; ++i) shrinkPore(tmp);
            for (int i = 0; i < maxHoleRadius * 4; ++i) { growPore(tmp); or_(tmp, self); }
            copyFrom(self, tmp);
            for (int i = 0; i < maxHoleRadius; ++i) growPore(tmp);
            for (int i = 0; i < maxHoleRadius * 3; ++i) { shrinkPore(tmp); and_(tmp, self); }
            copyFrom(self, tmp);
        }
    });
}

// voxlib _delense032 (growBox(2), a chain of median032 / FaceMedGrowToFrom, a merge, shrinkBox(2)).
// Labels outside the voxel type's range (voxlib compares and converts them differently) run voxlib.
template <Image I> bool _delense032(I& v, int nItrs, int nAdj0, int nAdj1, intOr<voxel_t<I>> lbl0, intOr<voxel_t<I>> lbl1) {
    using T = voxel_t<I>;
    auto inRange = [](auto l) { return double(l) >= double(std::numeric_limits<T>::lowest()) && double(l) <= double(std::numeric_limits<T>::max()); };
    if (get_backend() == Backend::Voxlib || !inRange(lbl0) || !inRange(lbl1))
        return ::_delense032(host_of(v), nItrs, nAdj0, nAdj1, lbl0, lbl1);
    vxhl::growBox(v, 2);
    on_device(v, [&](DeviceImage<T>& d) {
        DeviceImage<T> vimgo{VoxelImageT<T>(d.unsynced())};  // the grown image, copied on the host before any upload
        const T l0 = T(lbl0), l1 = T(lbl1);
        for (int i = 0; i < nItrs; ++i) median032(d, 25, nAdj1, l0, l1);
        FaceMedGrowToFrom(d, l1, l0, 1);
        FaceMedGrowToFrom(d, l0, l1, -1);
        for (int i = 0; i < 2 * nItrs; ++i) { median032(d, nAdj0, 25, l0, l1); FaceMedGrowToFrom(d, l0, l1, -1); }
        FaceMedGrowToFrom(d, l0, l1, -3);
        FaceMedGrowToFrom(d, l0, l1, -1);
        FaceMedGrowToFrom(d, l0, l1, -1);
        FaceMedGrowToFrom(vimgo, l1, l0, 2);
        FaceMedGrowToFrom(vimgo, l1, l0, 2);
        set_where_equal(d, vimgo, l1);
    });
    vxhl::shrinkBox(v, 2);
    return false;  // as voxlib (`return 0`)
}

template <Image I> void growPore(I& v) {
    detail::run_stencil<op::growPore, kernels::growPore<voxel_t<I>>>(v, 1, [&](auto& m) { ::growPore(m); });
}
